const incoming = $input.item.json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
return { json: {
  userId: body.userId || 'USER-EMP-4019',
  message: body.message || 'What is our travel reimbursement policy for domestic flights?',
  channel: body.channel || 'SLACK_DIRECT',
  testScenario: body.testScenario || null,
  managerApprovalAction: body.managerApprovalAction || 'PENDING',
  timestamp: new Date().toISOString()
}};

const row = $input.item.json || {};
const user = row.user_row;
const ctx = row.context || {};
if (!user) {
  return { json: { ...ctx, authError: `User ${ctx.userId || ''} was not found in enterprise_users`, authenticated: false } };
}
const allowedTiers = user.role === 'EXECUTIVE' ? ['EMPLOYEE','MANAGER','EXECUTIVE'] : user.role === 'MANAGER' ? ['EMPLOYEE','MANAGER'] : ['EMPLOYEE'];
return { json: {
  ...ctx,
  authenticated: true,
  authenticatedUser: { userId:user.user_id, name:user.name, email:user.email, role:user.role, department:user.department, managerEmail:user.manager_email, annualLeaveBalance:user.annual_leave_balance },
  rbacContext: { role:user.role, department:user.department, allowedTiers, verifiedAt:new Date().toISOString() }
}};

const item = $input.item.json;
const p = (item.message || '').toLowerCase();
let selectedTool = 'QUERY_KNOWLEDGE_BASE';
if (item.testScenario === 'TC-03' || item.testScenario === 'TC-04' || /\b(leave|vacation|time off)\b/.test(p)) selectedTool='SUBMIT_LEAVE_REQUEST';
else if (item.testScenario === 'TC-05' || /\b(vpn|ticket|error|laptop|support|it issue)\b/.test(p)) selectedTool='CREATE_IT_TICKET';
else if (item.testScenario === 'TC-06' || /\b(crm|client|contract|mrr|acme|globex)\b/.test(p)) selectedTool='LOOKUP_CRM_CLIENT';
return {json:{...item, aiOrchestrator:{selectedTool, decidedAt:new Date().toISOString(), model:'deterministic-router'}}};

const row=$input.item.json; const ctx=row.context||{}; const k=row.knowledge_row;
let result;
if (!k) result={status:'NO_AUTHORIZED_KNOWLEDGE_FOUND',groundedAnswer:'I could not find an authorized knowledge-base entry for this request.'};
else result={status:'SUCCESS',documentTitle:k.document_title,sectionTitle:k.section_title,requiredRoleTier:k.required_role_tier,groundedAnswer:`${k.chunk_content}\n\n**Source:** ${k.document_title} | ${k.section_title}`};
return {json:{...ctx,toolExecution:{toolName:'query_knowledge_base',result,executedAt:new Date().toISOString()}}};

const item=$input.item.json; const m=item.message||''; const dm=m.match(/(\d+)\s*days?/i); const days=dm?parseInt(dm[1],10):1;
const start=item.startDate||'2026-11-23'; const end=item.endDate||start;
return {json:{...item,leaveInput:{days,startDate:start,endDate:end,reason:m,approvalAction:item.managerApprovalAction||'PENDING'}}};

const row=$input.item.json; const ctx=row.context||{}; const u=row.user_row; const req=row.leave_row;
let result;
if (!u) result={status:'USER_NOT_FOUND',groundedAnswer:'Employee record was not found.'};
else if (!req) result={status:'DECLINED_INSUFFICIENT_BALANCE',currentBalance:u.annual_leave_balance,requestedDays:ctx.leaveInput.days,groundedAnswer:`Insufficient leave balance. Available: ${u.annual_leave_balance}; requested: ${ctx.leaveInput.days}.`};
else result={status:'PENDING_APPROVAL',requestId:req.request_id,requestedDays:req.days_count,groundedAnswer:`Leave request ${req.request_id} was saved as PENDING_APPROVAL. Manager approval is required before leave balance is deducted.`};
return {json:{...ctx,toolExecution:{toolName:'submit_leave_request',result,executedAt:new Date().toISOString()}}};

const item=$input.item.json; const p=(item.message||'').toLowerCase();
const urgency=p.includes('down')||p.includes('security')?'CRITICAL':p.includes('cannot')||p.includes('error')||p.includes('vpn')?'HIGH':'MEDIUM';
return {json:{...item,itInput:{ticketId:'IT-TICK-'+Date.now().toString().slice(-8),category:p.includes('vpn')?'VPN':p.includes('laptop')?'Laptop':'General IT Support',description:item.message||'IT support requested',urgency}}};

