WITH d AS (SELECT $1::jsonb AS j), ins AS (
 INSERT INTO public.enterprise_it_tickets(ticket_id,submitted_by,issue_category,description,urgency,ticket_status)
 SELECT d.j->'itInput'->>'ticketId', d.j->>'userId', d.j->'itInput'->>'category', d.j->'itInput'->>'description', d.j->'itInput'->>'urgency', 'OPEN'
 FROM d RETURNING ticket_id,issue_category,urgency,ticket_status
) SELECT d.j AS context, to_jsonb(ins) AS ticket_row FROM d,ins;

