const row=$input.item.json; const ctx=row.context||{}; const c=row.client_row;
const result=c?{...c,groundedAnswer:`**CRM Account Health: ${c.client_name}**
- Status: ${c.contract_status}
- Active MRR: ${c.active_mrr}
- Renewal: ${c.renewal_date}
- Account manager: ${c.account_manager}`}:{status:'NOT_FOUND',groundedAnswer:`No CRM client matched ${ctx.crmInput?.lookupName||'your search'}.`};
return {json:{...ctx,toolExecution:{toolName:'lookup_crm_client',result,executedAt:new Date().toISOString()}}};

const response=$input.item.json||{}; const payload=response.json||{}; const ctx=payload.auditContext||{}; const user=ctx.authenticatedUser||{}; const tool=ctx.toolExecution||{}; const result=tool.result||{};
const start=Date.parse(ctx.timestamp||''); const latencyMs=Number.isFinite(start)?Math.max(0,Date.now()-start):0;
const audit={userId:user.userId||ctx.userId||payload.userId||null,userPrompt:ctx.message||'',toolsInvoked:{toolName:tool.toolName||'UNKNOWN',status:result.status||result.rbacStatus||'SUCCESS',executedAt:tool.executedAt||null},agentResponse:payload.responseMarkdown||result.groundedAnswer||'',latencyMs};
return {json:{auditLedgerEntry:audit,chatResponse:audit.agentResponse,finalDeliveryStatus:'RESPONSE_DISPATCHED_AUDIT_PENDING'}};
